import * as React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import info from "../data/data.json";
import SEO from "../components/seo";
import Layout from "../components/layout";
import { AuditRequestButton } from "../components/auditRequestModal";

function Pill({ children }: { children: React.ReactNode }) {
  return (
    <span className="inline-flex items-center rounded-full border border-neutral/25 bg-primary px-3 py-1 text-xs font-medium text-accent">
      {children}
    </span>
  );
}

function BulletList({ items }: { items: string[] }) {
  return (
    <ul className="space-y-2 text-sm text-accent">
      {items.map((item) => (
        <li key={item} className="flex gap-2">
          <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 rounded-full bg-neutral" />
          <span className="min-w-0">{item}</span>
        </li>
      ))}
    </ul>
  );
}

export default function ServicesPage() {
  const { t } = useTranslation();
  const { language } = useI18next();

  const servicesItems = t("services.items", { returnObjects: true }) as Array<{
    key: string;
    title: string;
    desc: string;
    href: string;
  }>;

  return (
    <Layout data={info}>
      <main className={styles.container}>
        <section className="relative overflow-hidden border-b border-neutral/20 bg-[radial-gradient(circle_at_top_left,_rgba(255,255,255,0.6),_transparent_38%),linear-gradient(135deg,_rgba(255,240,224,0.92),_rgba(249,249,249,0.96))] py-16 sm:py-20 -mx-4 sm:-mx-8 lg:-mx-12 px-4 sm:px-8 lg:px-12">
          <div className="grid gap-8 lg:grid-cols-12">
            <div className="lg:col-span-8">
              <p className="text-xs font-semibold uppercase tracking-[0.18em] text-neutral">
                {t("servicesHub.kicker")}
              </p>
              <h1 className="mt-4 max-w-5xl text-3xl font-semibold tracking-tight text-accent sm:text-5xl">
                {t("servicesHub.h1")}
              </h1>
              <p className="mt-4 max-w-3xl text-base leading-7 text-neutral sm:text-lg">
                {t("servicesHub.lede")}
              </p>
              <div className="mt-6 flex flex-wrap gap-2">
                <Pill>{`${servicesItems.length} ${t("servicesHub.countLabel")}`}</Pill>
                {(t("servicesHub.heroPills", { returnObjects: true }) as string[]).map((pill) => (
                  <Pill key={pill}>{pill}</Pill>
                ))}
              </div>
              <div className="mt-8 flex flex-wrap gap-3">
                <AuditRequestButton
                  serviceName={t("contact.auditService") as string}
                  source="services.hero.primary"
                  className="inline-flex items-center rounded-2xl bg-accent px-5 py-3 text-sm font-semibold text-primary hover:opacity-90"
                >
                  {t("contact.cta")}
                </AuditRequestButton>
                <Link
                  to={language === "fr" ? "/fr/portfolio/" : "/en/portfolio/"}
                  className="inline-flex items-center rounded-2xl border border-neutral/25 bg-secondary px-5 py-3 text-sm font-semibold text-accent hover:bg-secondary/70"
                >
                  {t("selectedProjects.labels.viewSelectedProjects")}
                </Link>
              </div>
            </div>

            <div className="lg:col-span-4">
              <div className="rounded-2xl border border-neutral/20 bg-secondary/90 p-6 shadow-sm backdrop-blur-[2px]">
                <p className="text-sm font-semibold text-accent">{t("servicesHub.listTitle")}</p>
                <div className="mt-4">
                  <BulletList items={t("servicesHub.heroItems", { returnObjects: true }) as string[]} />
                </div>
              </div>
            </div>
          </div>
        </section>

        <section className="mt-12">
          <header className="space-y-3">
            <h2 className="text-2xl font-semibold tracking-tight text-accent sm:text-3xl">
              {t("servicesHub.listTitle")}
            </h2>
            <p className="max-w-3xl text-base text-neutral">
              {t("servicesHub.listDesc")}
            </p>
          </header>
        </section>

        <section className="mt-8 grid gap-6 md:grid-cols-2">
          {Array.isArray(servicesItems)
            ? servicesItems.map((service) => (
                <Link
                  key={service.key}
                  to={service.href}
                  className="group rounded-2xl border border-neutral-200 bg-secondary p-6 shadow-sm hover:-translate-y-0.5 transition-transform"
                >
                  <div className="flex items-start justify-between gap-4">
                    <div>
                      <h2 className="text-xl font-semibold text-accent group-hover:text-accent/90">
                        {service.title}
                      </h2>
                      <p className="mt-2 text-sm text-neutral">{service.desc}</p>
                    </div>
                    <span className="text-lg text-accent">→</span>
                  </div>
                </Link>
              ))
            : null}
        </section>

        <section className="mt-12 rounded-2xl border border-neutral-200 bg-secondary p-6 shadow-sm">
          <h2 className="text-2xl font-semibold text-accent">
            {t("selectedProjects.kicker")}
          </h2>
          <p className="mt-2 max-w-3xl text-neutral">
            {t("selectedProjects.lede")}
          </p>
          <div className="mt-5">
            <Link
              to={language === "fr" ? "/fr/portfolio/" : "/en/portfolio/"}
              className="inline-flex items-center rounded-2xl border border-neutral/25 bg-primary px-5 py-3 text-sm font-semibold text-accent hover:bg-primary/70"
            >
              {t("selectedProjects.labels.viewSelectedProjects")}
            </Link>
          </div>
        </section>
      </main>
    </Layout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full min-h-screen bg-primary text-accent p-4 sm:p-8 lg:p-12",
}

export const Head: HeadFC = ({ location, pageContext }) => {
  const language = (pageContext as { language?: string }).language || "fr";
  const pathname = language === "fr" ? "/fr/services/" : "/en/services/";
  const alternates = [
    { hrefLang: "fr", href: "https://riano.ca/fr/services/" },
    { hrefLang: "en", href: "https://riano.ca/en/services/" },
    { hrefLang: "x-default", href: "https://riano.ca/fr/services/" },
  ];

  return (
    <SEO
      data={info}
      titleKey="servicesHub.meta.title"
      descriptionKey="servicesHub.meta.description"
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={alternates}
      schemaType="ProfessionalService"
    />
  );
};
